{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Ofloxacin, a fluoroquinolone with the same quinolone-3-carboxylic acid core and a C7 basic amine, is almost completely absorbed after oral administration with approximately 100% bioavailability in humans; its very high transfer score makes this strong supportive evidence for high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Trovafloxacin, a fluoroquinolone with a lipophilic N1 substituent and C8 halogen, has a mean absolute oral bioavailability of 87.6% in healthy volunteers, directly supporting high bioavailability for the query's fluoroquinolone scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Moxifloxacin, a fluoroquinolone with a C7 basic bicyclic amine and N1 cyclopropyl group, has an absolute oral bioavailability of 86-92% in healthy volunteers, supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Levofloxacin, a close structural relative of ofloxacin, is well absorbed from the gastrointestinal tract with bioavailability approaching 100%, reinforcing the high-absorption pattern of this quinolone class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Finafloxacin, a fluoroquinolone with a similar quinolone core, shows oral bioavailability ranging from about 60% to essentially complete in volunteers, supporting a high prediction even at the lower end.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a fluoroquinolone-3-carboxylic acid with a C7 basic amine and lipophilic N1 substituent. Multiple high-transfer fluoroquinolone analogues show absolute oral bioavailability of 86-100%, and even the least absorbed fluoroquinolone evidence remains well above the 20% threshold. Therefore the query is predicted to have high oral bioavailability.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement is available for the exact query molecule.",
    "The specific influence of the C8 chloro and spirocyclopropyl-pyrrolidine substituents on absorption is not directly measured, but the overall fluoroquinolone class evidence strongly supports high bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

